import React, { useState } from 'react';
import { db, collection, addDoc } from '../firebase';
import { InspectionData } from '../types';
import { Loader2, CheckCircle, AlertCircle, Save } from 'lucide-react';

export const InspectionForm: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<Omit<InspectionData, 'id' | 'createdAt'>>({
    tester: '',
    date: new Date().toISOString().split('T')[0],
    grade: '',
    lot: '',
    rating: 0,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'rating' ? parseFloat(value) : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(false);

    try {
      await addDoc(collection(db, "inspections"), {
        ...formData,
        createdAt: Date.now()
      });
      setSuccess(true);
      setFormData({
        tester: '',
        date: new Date().toISOString().split('T')[0],
        grade: '',
        lot: '',
        rating: 0,
      });
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      console.error("Error adding document: ", err);
      setError("Failed to save data. Please check your connection.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden">
      <div className="bg-blue-600 p-6">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
          <Save className="w-6 h-6" />
          New Inspection
        </h2>
        <p className="text-blue-100 mt-1">Record a new pipe surface roughness evaluation.</p>
      </div>

      <form onSubmit={handleSubmit} className="p-6 space-y-6">
        {success && (
          <div className="bg-green-50 text-green-700 p-4 rounded-lg flex items-center gap-2 animate-fade-in border border-green-200">
            <CheckCircle className="w-5 h-5" />
            <span>Inspection recorded successfully!</span>
          </div>
        )}

        {error && (
          <div className="bg-red-50 text-red-700 p-4 rounded-lg flex items-center gap-2 animate-fade-in border border-red-200">
            <AlertCircle className="w-5 h-5" />
            <span>{error}</span>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Tester Name</label>
            <input
              required
              type="text"
              name="tester"
              value={formData.tester}
              onChange={handleChange}
              placeholder="e.g. John Doe"
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Date</label>
            <input
              required
              type="date"
              name="date"
              value={formData.date}
              onChange={handleChange}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Pipe Grade</label>
             <div className="relative">
                <input
                  required
                  list="grades"
                  type="text"
                  name="grade"
                  value={formData.grade}
                  onChange={handleChange}
                  placeholder="Select or type grade"
                  className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
                />
                <datalist id="grades">
                  <option value="304 Stainless" />
                  <option value="316L Stainless" />
                  <option value="Carbon Steel" />
                  <option value="PVC Schedule 40" />
                  <option value="Copper Type L" />
                </datalist>
             </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Lot Number</label>
            <input
              required
              type="text"
              name="lot"
              value={formData.lot}
              onChange={handleChange}
              placeholder="e.g. LOT-2023-X99"
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
            />
          </div>
        </div>

        <div className="space-y-4 pt-4 border-t border-gray-100">
          <div className="flex justify-between items-center">
             <label className="text-sm font-semibold text-gray-700">Roughness Rating (Ra)</label>
             <span className="text-2xl font-bold text-blue-600">{formData.rating.toFixed(1)} <span className="text-sm text-gray-400 font-normal">μm</span></span>
          </div>

          <input
            type="range"
            name="rating"
            min="0"
            max="10"
            step="0.1"
            value={formData.rating}
            onChange={handleChange}
            className="w-full h-3 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
          />
          <div className="flex justify-between text-xs text-gray-400 px-1">
            <span>0 (Smooth)</span>
            <span>5 (Medium)</span>
            <span>10 (Rough)</span>
          </div>
        </div>

        <button
          type="submit"
          disabled={loading}
          className={`w-full py-4 rounded-lg font-bold text-lg shadow-md transition-all flex items-center justify-center gap-2
            ${loading 
              ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
              : 'bg-blue-600 hover:bg-blue-700 text-white hover:shadow-lg active:transform active:scale-[0.99]'
            }`}
        >
          {loading ? <Loader2 className="animate-spin" /> : <Save />}
          {loading ? 'Saving Record...' : 'Save Inspection'}
        </button>
      </form>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { db, collection, query, orderBy, onSnapshot, deleteDoc, doc } from '../firebase';
import { InspectionData } from '../types';
import { Trash2, Search, Calendar, User, Box, Activity, FileText } from 'lucide-react';

export const InspectionHistory: React.FC = () => {
  const [inspections, setInspections] = useState<InspectionData[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const q = query(collection(db, "inspections"), orderBy("createdAt", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      } as InspectionData));
      setInspections(data);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      try {
        await deleteDoc(doc(db, "inspections", id));
      } catch (err) {
        console.error("Error deleting document: ", err);
      }
    }
  };

  const filteredInspections = inspections.filter(item => 
    item.tester.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.lot.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.grade.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <FileText className="w-6 h-6 text-blue-600"/>
            History Log
        </h2>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search logs..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 pr-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 w-full md:w-64 outline-none"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {filteredInspections.length === 0 ? (
           <div className="text-center py-12 bg-white rounded-xl shadow-sm">
             <div className="bg-gray-100 p-4 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                <Box className="w-8 h-8 text-gray-400" />
             </div>
             <p className="text-gray-500 text-lg">No records found</p>
           </div>
        ) : (
          filteredInspections.map((item) => (
            <div key={item.id} className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow group relative">
                <button 
                  onClick={() => item.id && handleDelete(item.id)}
                  className="absolute top-4 right-4 p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full opacity-0 group-hover:opacity-100 transition-all"
                  title="Delete Record"
                >
                  <Trash2 className="w-5 h-5" />
                </button>

                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                    <div className="space-y-1">
                        <div className="flex items-center gap-2 text-sm text-gray-500 mb-1">
                           <Calendar className="w-4 h-4" />
                           <span>{item.date}</span>
                           <span className="text-gray-300">|</span>
                           <User className="w-4 h-4" />
                           <span className="font-medium text-gray-700">{item.tester}</span>
                        </div>
                        <div className="flex items-center gap-3">
                           <h3 className="text-lg font-bold text-gray-900">{item.lot}</h3>
                           <span className="bg-gray-100 text-gray-600 px-2 py-0.5 rounded text-xs font-semibold uppercase tracking-wider border border-gray-200">
                             {item.grade}
                           </span>
                        </div>
                    </div>

                    <div className="flex items-center gap-4 mt-2 sm:mt-0">
                        <div className="text-right">
                            <p className="text-xs text-gray-500 uppercase font-semibold">Roughness (Ra)</p>
                            <div className={`text-2xl font-bold flex items-center gap-1 justify-end
                                ${item.rating < 3 ? 'text-green-600' : item.rating < 7 ? 'text-orange-500' : 'text-red-600'}
                            `}>
                                <Activity className="w-5 h-5" />
                                {item.rating.toFixed(1)}
                            </div>
                        </div>
                        <div className={`w-2 h-12 rounded-full hidden sm:block
                             ${item.rating < 3 ? 'bg-green-500' : item.rating < 7 ? 'bg-orange-500' : 'bg-red-500'}
                        `}></div>
                    </div>
                </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { db, collection, query, orderBy, onSnapshot } from '../firebase';
import { InspectionData } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from 'recharts';
import { BarChart2, TrendingUp, AlertTriangle } from 'lucide-react';

export const AnalyticsDashboard: React.FC = () => {
  const [data, setData] = useState<InspectionData[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Limit to last 50 entries for chart clarity
    const q = query(collection(db, "inspections"), orderBy("createdAt", "asc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const rawData = snapshot.docs.map(doc => ({
         ...doc.data()
      } as InspectionData));
      setData(rawData);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  if (loading) return <div className="h-64 flex items-center justify-center text-gray-400">Loading Analytics...</div>;

  // Process data for charts
  const recentData = data.slice(-20); // Last 20 records

  const avgRating = data.length > 0 
    ? (data.reduce((acc, curr) => acc + curr.rating, 0) / data.length).toFixed(2)
    : "0.00";

  const highRoughnessCount = data.filter(d => d.rating > 7).length;

  return (
    <div className="space-y-6">
       {/* Summary Cards */}
       <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
              <div>
                 <p className="text-sm text-gray-500 font-medium">Total Inspections</p>
                 <h3 className="text-3xl font-bold text-gray-800">{data.length}</h3>
              </div>
              <div className="bg-blue-50 p-3 rounded-full text-blue-600">
                <BarChart2 className="w-6 h-6" />
              </div>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
              <div>
                 <p className="text-sm text-gray-500 font-medium">Avg Roughness (Ra)</p>
                 <h3 className="text-3xl font-bold text-gray-800">{avgRating}</h3>
              </div>
              <div className="bg-green-50 p-3 rounded-full text-green-600">
                <TrendingUp className="w-6 h-6" />
              </div>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
              <div>
                 <p className="text-sm text-gray-500 font-medium">High Roughness ({'>'}7)</p>
                 <h3 className="text-3xl font-bold text-gray-800">{highRoughnessCount}</h3>
              </div>
              <div className="bg-orange-50 p-3 rounded-full text-orange-600">
                <AlertTriangle className="w-6 h-6" />
              </div>
          </div>
       </div>

       {/* Chart */}
       <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Recent Roughness Trend</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={recentData} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                <CartesianGrid stroke="#f3f4f6" strokeDasharray="3 3" vertical={false} />
                <XAxis 
                    dataKey="lot" 
                    stroke="#9ca3af" 
                    tick={{fontSize: 12}} 
                    tickFormatter={(value) => value.length > 8 ? value.substring(0,8)+'...' : value}
                />
                <YAxis stroke="#9ca3af" tick={{fontSize: 12}} domain={[0, 10]} />
                <Tooltip 
                    contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{ stroke: '#3b82f6', strokeWidth: 1 }}
                />
                <Line 
                    type="monotone" 
                    dataKey="rating" 
                    stroke="#3b82f6" 
                    strokeWidth={3}
                    dot={{ fill: '#3b82f6', r: 4, strokeWidth: 2, stroke: '#fff' }}
                    activeDot={{ r: 6, strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
       </div>
    </div>
  );
};

import React, { useState } from 'react';
import { InspectionForm } from './components/InspectionForm';
import { InspectionHistory } from './components/InspectionHistory';
import { AnalyticsDashboard } from './components/AnalyticsDashboard';
import { LayoutDashboard, PlusCircle, History, Menu, X, GripHorizontal } from 'lucide-react';

type View = 'dashboard' | 'new' | 'history';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
    { id: 'new', label: 'New Inspection', icon: <PlusCircle className="w-5 h-5" /> },
    { id: 'history', label: 'History', icon: <History className="w-5 h-5" /> },
  ];

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      {/* Sidebar Navigation (Desktop) */}
      <aside className="hidden md:flex flex-col w-64 bg-slate-900 text-white min-h-screen fixed left-0 top-0 z-30 shadow-2xl">
        <div className="p-6 border-b border-slate-700">
           <div className="flex items-center gap-3">
             <div className="bg-blue-600 p-2 rounded-lg">
               <GripHorizontal className="w-6 h-6 text-white" />
             </div>
             <div>
               <h1 className="text-xl font-bold tracking-tight">PipeSurface</h1>
               <p className="text-xs text-slate-400">Quality Control Pro</p>
             </div>
           </div>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id as View)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200
                ${currentView === item.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50 translate-x-1' 
                  : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                }
              `}
            >
              {item.icon}
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-700 text-center">
            <p className="text-xs text-slate-500">v1.0.0 &copy; 2023</p>
        </div>
      </aside>

      {/* Mobile Header */}
      <header className="md:hidden bg-slate-900 text-white p-4 flex justify-between items-center sticky top-0 z-40 shadow-md">
         <div className="flex items-center gap-2">
             <div className="bg-blue-600 p-1.5 rounded-lg">
               <GripHorizontal className="w-5 h-5 text-white" />
             </div>
             <span className="font-bold text-lg">PipeSurface</span>
         </div>
         <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2">
            {isMobileMenuOpen ? <X /> : <Menu />}
         </button>
      </header>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-30 bg-slate-900/95 backdrop-blur-sm pt-20 px-6">
           <nav className="space-y-4">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    setCurrentView(item.id as View);
                    setIsMobileMenuOpen(false);
                  }}
                  className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl text-lg font-medium transition-all
                    ${currentView === item.id 
                      ? 'bg-blue-600 text-white' 
                      : 'bg-slate-800 text-slate-300'
                    }
                  `}
                >
                  {item.icon}
                  <span>{item.label}</span>
                </button>
              ))}
           </nav>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 md:ml-64 p-4 md:p-8 max-w-6xl mx-auto w-full pt-6">
        <div className="mb-8">
           <h2 className="text-2xl md:text-3xl font-bold text-gray-800">
             {navItems.find(i => i.id === currentView)?.label}
           </h2>
           <p className="text-gray-500 mt-1">
             {currentView === 'dashboard' && 'Overview of inspection performance metrics.'}
             {currentView === 'new' && 'Enter details for a new pipe quality assessment.'}
             {currentView === 'history' && 'Browse and manage past inspection records.'}
           </p>
        </div>

        <div className="animate-fade-in-up">
           {currentView === 'dashboard' && <AnalyticsDashboard />}
           {currentView === 'new' && <InspectionForm />}
           {currentView === 'history' && <InspectionHistory />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';

export interface InspectionData {
  id?: string;
  tester: string;
  date: string; // ISO Date string YYYY-MM-DD
  grade: string;
  lot: string;
  rating: number; // Roughness value (e.g., Ra)
  createdAt: number; // Timestamp
}

export interface NavItem {
  id: string;
  label: string;
  icon: React.ReactNode;
}

payload.text:
ใช่ครับ จากโค้ดที่คุณให้มาและที่ผมได้สร้างให้ **การเชื่อมต่อ Firebase ถูกตั้งค่าเรียบร้อยแล้ว** ครับ

1.  ไฟล์ `firebase.ts` ได้ระบุค่า `firebaseConfig` (apiKey, projectId, etc.) ถูกต้องตามที่คุณให้มา
2.  มีการเรียกใช้ `initializeApp` และ `getFirestore` เพื่อเตรียมพร้อมสำหรับการบันทึกและดึงข้อมูล
3.  ในหน้าต่างต่างๆ (Form, History, Dashboard) มีการเรียกใช้ `db` เพื่อติดต่อกับ Database แล้ว

**สิ่งที่ต้องทำเพิ่มใน Firebase Console (ถ้ายังไม่ได้ทำ):**
เนื่องจากโค้ดพร้อมแล้ว แต่ฝั่ง Server (Firebase Console) ต้องเปิดอนุญาตให้เขียนข้อมูลได้ด้วยครับ:
1.  ไปที่ **Firebase Console** > **Firestore Database**
2.  กดสร้าง Database (ถ้ายังไม่มี)
3.  ไปที่แท็บ **Rules** และเปลี่ยน Code ให้เป็นแบบนี้เพื่อทดสอบ (อนุญาตให้ทุกคนอ่าน/เขียนได้):
    ```
    rules_version = '2';
    service cloud.firestore {
      match /databases/{database}/documents {
        match /{document=**} {
          allow read, write: if true;
        }
      }
    }
    ```
    *(หมายเหตุ: เมื่อใช้งานจริงควรปรับ Rules ให้ปลอดภัยขึ้น)*

เพื่อให้คุณมั่นใจยิ่งขึ้น ผมจะอัปเดตไฟล์ `App.tsx` ให้มีสถานะบอกว่า **"System Online"** ที่แถบเมนู เพื่อยืนยันว่า App พร้อมทำงานครับ

